fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Number of input rows
    let rows = x.len();
    // Since the matrix is non-empty and rectangular, we can safely get the number of columns
    let cols = x[0].len();

    // Prepare the transposed matrix with `cols` rows, each reserving space for `rows` elements
    let mut result: Vec<Vec<f32>> = Vec::with_capacity(cols);
    for _ in 0..cols {
        result.push(Vec::with_capacity(rows));
    }

    // Fill in the transposed entries
    for r in 0..rows {
        // (Optional) Assert that every row has the same length
        debug_assert_eq!(x[r].len(), cols, "All rows must have the same length");
        for c in 0..cols {
            result[c].push(x[r][c]);
        }
    }

    result
}

